WebControls.wcOnClick:
m1.tapAddScrap({
	parameters : {row : this.fields }
});

m1.callServerFunction({
	serverFunction: 'adjustBinQuantity',
	parameters: {
		part: this.fields.imrPartID, 
		revision: this.fields.imrPartRevisionID, 
		warehouse: this.fields.imbWarehouseID, 
		bin: this.fields.imbPartBinID,
		newQuantity: this.newQuantity.getValue(),
	}, 
	onReturn: function () {
		m1.backTo({
			screen: "part",
			parameters: {
				part: this.fields.imrPartID,
				revision: this.fields.imrPartRevisionID
			}
		});
	}, 
	scope: this
});

WebControls.wcOnChange:
m1.callServerFunction({
	serverFunction: "getLotQuantityOnHand",
	parameters: {
		part: this.fields.imrPartID,
		revision: this.fields.imrPartRevisionID,
		warehouse: this.fields.imbWarehouseID,
		bin: this.fields.imbPartBinID,
		lotNumber: this.lotNumber.getValue(),
	}, 
	onReturn: function (value) {
		this.quantityToTransfer.setValue(value);
	}, 
	scope: this
});

WebControls.wcOnClick:
currentSettings = this.settings;

m1.forwardTo({
	list:"bins",
	filters: {
		imbPartID: this.fields.imrPartID,
		imbPartRevisionID: this.fields.imrPartRevisionID
	},
	onExit: function () {
		warehouse = this.fields.imbWarehouseID;
		bin = this.fields.imbPartBinID;

		m1.backTo({
			screen: "binTransfer",
			parameters: currentSettings.parameters,
			reload: false,
			onReady: function() {
				this.toWarehouse.setValue(warehouse);
				this.toBin.setValue(bin);
			}
		});
	}
});

currentSettings = this.settings;

m1.forwardTo({
	list:"lotNumbers",
	filters: {
		ablPartID: this.fields.imrPartID,
		ablPartRevisionID: this.fields.imrPartRevisionID,
		ablPartWarehouseLocationID: this.fields.imbWarehouseID,
		ablPartBinID: this.fields.imbPartBinID
	},
	onExit: function () {
		lotNumber = this.fields.ablLotNumberID;

		m1.backTo({
			screen: "binTransfer",
			parameters: currentSettings.parameters,
			reload: false,
			onReady: function() {
				this.lotNumber.setValue(lotNumber, true);
			}
		});
	}
});

m1.forwardTo({
	list:"serialNumbers",
	filters: {
		imsPartID: this.fields.imrPartID,
		imsPartRevisionID: this.fields.imrPartRevisionID,
		imsPartWarehouseLocationID: this.fields.imbWarehouseID,
		imsPartBinID: this.fields.imbPartBinID
	},
	onExit: function () {
		serialNumber = this.fields.imsSerialNumberID;



		m1.backTo({
			screen: "binTransfer",
			parameters: {
				part: this.fields.imsPartID,
				revision: this.fields.imsPartRevisionID,
				warehouse: this.fields.imsPartWarehouseLocationID,
				bin: this.fields.imsPartBinID
			},
			reload: false,
			onReady: function() {
				this.serialNumber.setValue(serialNumber, true);
				this.quantityToTransfer.setValue(1);
			}
		});
	}
});

m1.callServerFunction({
	serverFunction: 'transferToBin',
	parameters: {
		part: this.fields.imrPartID, 
		revision: this.fields.imrPartRevisionID, 
		fromWarehouse: this.fields.imbWarehouseID, 
		fromBin: this.fields.imbPartBinID,
		toWarehouse: this.toWarehouse.getValue(), 
		toBin: this.toBin.getValue(),
		quantity: this.quantityToTransfer.getValue(),
		lotNumber: this.lotNumber.getValue(),
		serialNumber: this.serialNumber.getValue(),
	}, 
	onReturn: function () {
		if (this.fields.impTrackLotNumbers == '1' || this.fields.impTrackSerialNumbers == '1')
		{
			this.reload();
		}
		else
		{
			m1.backTo({
				screen: "part",
				parameters: {
					part: this.fields.imrPartID,
					revision: this.fields.imrPartRevisionID
				}
			});
		}
	}, 
	scope: this
});

m1.tapCreateInspection({
	parameters : {
		row : this.fields
	} 
});

var ShiftId = this.fields.lmeDefaultShiftID;
m1.tapClockIn({
	parameters: { shift: ShiftId }
});

workQueueFilters = {};

if( m1.options.filterQueueEmpWc )
	workQueueFilters.xawWorkCenterID = this.fields.lmeDefaultWorkCenterID;

if( m1.options.filterQueueDepartment )
	workQueueFilters.xawProductionDepartmentID = this.fields.lmeHomeProductionDepartmentID;

m1.forwardTo({
	list:"workQueue",
	parameters: {employee: m1.employee},
	filters: workQueueFilters
});

m1.tapEndIndirect({
      parameters :
      {
         timecardLine :
          {
                  timecardid : this.fields.lmlTimecardID,
                  timecardlineid: this.fields.lmlTimecardLineID,
                  labordescription: this.laborDescription.getValue()
            }
        }
});

m1.tapEndProduction({
	parameters :{
		timecardid : this.fields.lmlTimecardID,
		timecardlineid : this.fields.lmlTimecardLineID,
		jobid :  this.fields.lmlJobID,
		jobassemblyid : this.fields.lmlJobAssemblyID,
		joboperationid : this.fields.lmlJobOperationID,
		completiontype : this.completionType.getValue(),
		goodquantity : this.goodQuantity.getValue(),
		scrapreason : this.scrapReason.getValue(),
		scrapquantity : this.scrapQuantity.getValue(),
		reworkreason : this.reworkReason.getValue(),
		reworkquantity : this.reworkQuantity.getValue(),
		labordescription: this.laborDescription.getValue()
	}
});

m1.tapEndSetup ({
	parameters : {
		timecardid : this.fields.lmlTimecardID,
		timecardlineid : this.fields.lmlTimecardLineID,
		labordescriptiontext : this.laborDescription.getValue(),
		labordescriptionrtf : this.laborDescription.getValue(),
		completion : this.completion.getValue(),
		setuppercent : this.setupPercent.getValue()
	}
});

m1.tapStartProduction({
	parameters : {
		timecardid : this.fields.lmlTimecardID,
		timecardlineid : this.fields.lmlTimecardLineID,
		labordescriptiontext : this.laborDescription.getValue(),
		labordescriptionrtf : this.laborDescription.getValue(),
		completion : this.completion.getValue(),
		setuppercent : this.setupPercent.getValue()
	}
});

m1.forwardTo({
      screen: "endIndirect",
      parameters: {timecard: this.fields.lmlTimecardID, line: this.fields.lmlTimecardLineID}
});

m1.tapStartIndirect({
	parameters : { indirectlaborid: this.fields.lmiIndirectLaborID }
});

m1.forwardTo({
	list: "inventoryCountLines",
	filters:{
		imqInventoryCountID: this.fields.imnInventoryCountID
	}
});

m1.mode = "count";
m1.countMode.count = this.fields.imnInventoryCountID;

m1.forwardTo({
	list: "inventoryCountLines",
	filters:{
		imqInventoryCountID: this.fields.imnInventoryCountID
	}
});

m1.countMode.count = null;

m1.mode = "part";
m1.backTo({ list: "inventoryCounts" });

m1.callServerFunction({
	serverFunction: "saveRowInTable",
	parameters: {
		table: "InventoryCountLines", 
		row: {
			imqInventoryCountID: this.fields.imqInventoryCountID,
			imqInventoryCountLineID: this.fields.imqInventoryCountLineID,
			imqFinalCount: this.fields.imqFinalCount,
			imqCountedBy: this.fields.imqCountedBy,
			imqCountedDate: "now"
		}
	}, 
	onReturn: function () {
		m1.backTo({
			list: "inventoryCountLines",
			filters:{
				imqInventoryCountID: this.fields.imqInventoryCountID
			}
		});
	}, 
	scope: this
});

m1.forwardTo({
	list: "jobMaterials",
	filters: {
		jmmJobID: this.fields.jmpJobID
	}
});

m1.mode = "job";
m1.jobMode.job = this.fields.jmpJobID;
m1.jobMode.jobAssembly = null;

m1.forwardTo({
	list: "jobMaterials",
	filters: {
		jmmJobID: this.fields.jmpJobID
	}
});

m1.jobMode.job = null;
m1.jobMode.jobAssembly = null;

m1.mode = "part";
mM1.backTo({ list: "jobs" });

m1.forwardTo({
	list: "jobMaterials",
	filters: {
		jmmJobID: this.fields.jmaJobID,
		jmmJobAssemblyID: this.fields.jmaJobAssemblyID
	}
});

m1.mode = "job";
m1.jobMode.job = this.fields.jmaJobID;
m1.jobMode.assembly = this.fields.jmaJobAssemblyID;

m1.forwardTo({
	list: "jobMaterials",
	filters: {
		jmmJobID: this.fields.jmaJobID,
		jmmJobAssemblyID: this.fields.jmaJobAssemblyID
	}
});

m1.mode = "part";
m1.jobMode.job = null;
m1.jobMode.assembly = null;

if(this.fields.jmaParentAssemblyID == 0) {
	m1.backTo({
		screen: "job",
		parameters:{
			job: this.fields.jmaJobID
		}
	});
}
else {
	m1.backTo({
		screen: "jobAssembly",
		parameters: {
			job: this.fields.jmaJobID,
			assembly: this.fields.jmaParentAssemblyID
		}
	});
}

m1.tapIssueMaterial({
	parameters: {
		jobmaterialid : this.fields.jmmJobMaterialID,
		partid : this.fields.jmmPartID, 
		partrevisionid : this.fields.jmmPartRevisionID,
		partwarehouselocationid : this.fields.jmmPartWarehouseLocationID,
		partbinid : this.fields.jmmPartBinID,  
		totalissue : this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived,
		quantitytoissue : this.quantityToIssue.getValue(), 
		lotnumber :  this.lotNumber.getValue(),
		serialnumber : this.serialNumber.getValue() 
	}
});

m1.tapIssueMaterial({
	parameters: {
		jobmaterialid : this.fields.jmmJobMaterialID,
		partid : this.fields.jmmPartID, 
		partrevisionid : this.fields.jmmPartRevisionID,
		partwarehouselocationid : this.fields.jmmPartWarehouseLocationID,
		partbinid : this.fields.jmmPartBinID,  
		totalissue : this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived,
		quantitytoissue : this.quantityToIssue.getValue(), 
		lotnumber :  this.lotNumber.getValue(),
		serialnumber : this.serialNumber.getValue() 
	}
});

WebControls.wcOnChange:
m1.callServerFunction({
	serverFunction: "getLotQuantityOnHand",
	parameters: {
		part: this.fields.jmmPartID, 
		revision: this.fields.jmmPartRevisionID, 
		warehouse: this.fields.jmmPartWarehouseLocationID, 
		bin: this.fields.jmmPartBinID, 
		lotNumber: this.lotNumber.getValue(),
	}, 
	onReturn: function (value) {
		lotQty = parseFloat(value);
		qtyToIssue = this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived;

		if(qtyToIssue < 0)
			qtyToIssue = 0;

		if(lotQty < qtyToIssue)
			this.quantityToIssue.setValue(lotQty);
		else
			this.quantityToIssue.setValue(qtyToIssue);
	}, 
	scope: this
});

m1.callServerFunction({
	serverFunction: 'getLotQuantityOnHand',
	parameters: {
		part: this.fields.jmmPartID, 
		revision: this.fields.jmmPartRevisionID, 
		warehouse: this.fields.jmmPartWarehouseLocationID, 
		bin: this.fields.jmmPartBinID, 
		lotNumber: this.lotNumber.getValue(),
	}, 
	onReturn: function (value) {
		lotQty = parseFloat(value);
		qtyToIssue = this.fields.jmmEstimatedQuantity - this.fields.jmmQuantityReceived;

		if(qtyToIssue < 0)
			qtyToIssue = 0;

		if(lotQty < qtyToIssue)
			this.quantityToIssue.setValue(lotQty);
		else
			this.quantityToIssue.setValue(qtyToIssue);
	}, 
	scope: this
});

WebControls.wcOnClick:
m1.forwardTo({
	list:"lotNumbers",
	filters: {
		ablPartID: this.fields.jmmPartID,
		ablPartRevisionID: this.fields.jmmPartRevisionID
	},
	onExit: function () {
		lotNumber = this.fields.ablLotNumberID;
		warehouse = this.fields.ablPartWarehouseLocationID;
		bin = this.fields.ablPartBinID;

		m1.backTo({
			screen: "jobMaterial",
			reload: false,
			onReady: function() {
				this.warehouse.setValue(warehouse);
				this.bin.setValue(bin);
				this.lotNumber.setValue(lotNumber, true);
			}
		});
	}
});

m1.forwardTo({
	list:"lotNumbers",
	filters: {
		ablPartID: this.fields.jmmPartID,
		ablPartRevisionID: this.fields.jmmPartRevisionID
	},
	onExit: function () {
		lotNumber = this.fields.ablLotNumberID;
		warehouse = this.fields.ablPartWarehouseLocationID;
		bin = this.fields.ablPartBinID;
		m1.backTo({
			screen: "jobMaterial",
			reload: false,
			onReady: function() {
				this.warehouse.setValue(warehouse);
				this.bin.setValue(bin);
				this.lotNumber.setValue(lotNumber, true);
			}
		});
	}
});

m1.forwardTo({
	list:"serialNumbers",
	filters: {
		imsPartID: this.fields.jmmPartID,
		imsPartRevisionID: this.fields.jmmPartRevisionID
	},
	onExit: function () {
		serialNumber = this.fields.imsSerialNumberID;
		m1.backTo({
			screen: "jobMaterial",
			reload: false,
			onReady: function() {
				this.serialNumber.setValue(serialNumber, true);
				this.quantityToIssue.setValue(1);
			}
		});
	}
});

m1.forwardTo({
	list:"serialNumbers",
	filters: {
		imsPartID: this.fields.jmmPartID,
		imsPartRevisionID: this.fields.jmmPartRevisionID
	},
	onExit: function () {
		serialNumber = this.fields.imsSerialNumberID;
		m1.backTo({
			screen: "jobMaterial",
			reload: false,
			onReady: function() {
				this.serialNumber.setValue(serialNumber, true);
			}
		});
	}
});

m1.forwardTo({
	screen: "addScrap",
	parameters: {
		timecard: this.fields.lmlTimecardID, 
		line: this.fields.lmlTimecardLineID
	}
});

m1.forwardTo({
	screen: 'createInspection',
	parameters: {
		job: this.fields.jmoJobID, 
		assembly: this.fields.jmoJobAssemblyID, 
		operation: this.fields.jmoJobOperationID
	}
});

if(this.fields.lmlWorkType == '1')
{
	m1.forwardTo({screen: 'endSetup', parameters: {timecard: this.fields.lmlTimecardID, line: this.fields.lmlTimecardLineID}});
}
else
{
	m1.forwardTo({screen:'endProduction', parameters: {timecard: this.fields.lmlTimecardID, line: this.fields.lmlTimecardLineID}});
}

m1.tapStartSetup({
	parameters:{
		jobid: this.fields.jmoJobID, 
		jobassemblyid : this.fields.jmoJobAssemblyID,
		operationid : this.fields.jmoJobOperationID,
	}
});

materialFilters = {jmmJobID: m1.job}

if(m1.options.filterMaterialByAssembly)
	materialFilters.jmmJobAssemblyID = m1.jobAssembly;

if(m1.options.filterMaterialByOperation)
	materialFilters.jmmRelatedJobOperationID = m1.jobOperation;

m1.forwardTo({list: "jobMaterials", filters: materialFilters});

m1.tapPartIssueMaterial({
	parameters :{
		job: this.fields.jmmJobID, 
		assembly: this.fields.jmmJobAssemblyID, 
		material: this.fields.jmmJobMaterialID, 
		part: this.fields.imrPartID, 
		revision: this.fields.imrPartRevisionID, 
		warehouse: this.fields.jmmPartWarehouseLocationID, 
		bin: this.fields.jmmPartBinID, 
		quantity: this.quantityToIssue.getValue(),
		lotnumber: this.lotNumber.getValue(),
		serialnumber: this.serialNumber.getValue() 
	} 
});

